package com.eye.core;
import java.nio.file.*;import java.time.*;import java.util.*;
public class AccountingAcceptance {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 public static void main(String[] args)throws Exception{Path f=Path.of(args[0],"accounting-"+System.nanoTime()+".properties");var s=new ComputerActivity(f,ZoneOffset.UTC);String a="c:\\apps\\chatgpt.exe";Instant t=Instant.parse("2026-10-05T23:59:58Z");var sample=new ComputerActivity.Sample(true,true,a);s.sample(t,0,sample);s.sample(t.plusSeconds(4),4_000_000_000L,sample);s.sampleRunning(t,0,Set.of(a,a.toUpperCase(Locale.ROOT)));s.sampleRunning(t.plusSeconds(4),4_000_000_000L,Set.of(a));LocalDate before=LocalDate.of(2026,10,5),after=before.plusDays(1);check(s.day(before).apps().get(a)==2000,"foreground before midnight");check(s.day(after).apps().get(a)==2000,"foreground after midnight");check(s.applicationRuntime(before).get(a)==2000,"runtime midnight");check(s.applicationRuntime(after).get(a)==2000,"runtime dedup");check(s.applicationUsageTotals().get(a)==4000,"totals index");s.sampleRunning(t.plusSeconds(64),64_000_000_000L,Set.of(a));check(s.applicationRuntime(after).get(a)==2000,"sleep excluded");var copy=s.applicationRuntime(after);copy.clear();check(s.applicationRuntime(after).size()==1,"defensive snapshot");s.close();var r=new ComputerActivity(f,ZoneOffset.UTC);check(r.applicationUsageTotals().get(a)==4000&&r.day(after).apps().get(a)==2000&&r.applicationRuntime(after).get(a)==2000,"legacy format reload");r.close();System.out.println("PASS foreground/runtime midnight split, process dedup, sleep gaps, totals, detached snapshots and persistence reload");}
}
